 static final class Http implements MaterialApi.Transport {final String base,token;Http(String base,String token){this.base=base;this.token=token;}public MaterialApi.Response exchange(String path,byte[] body)throws IOException{HttpURLConnection c=(HttpURLConnection)new URL(base+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(3000);c.setReadTimeout(5000);c.setRequestProperty("Authorization","Bearer "+token);if(body!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body);}}int status=c.getResponseCode();ByteArrayOutputStream out=new ByteArrayOutputStream();InputStream stream=status>=400?c.getErrorStream():c.getInputStream();if(stream!=null)try(InputStream in=stream){byte[] block=new byte[8192];int n;while((n=in.read(block))!=-1){yes(out.size()+n<=262144);out.write(block,0,n);}}c.disconnect();return new MaterialApi.Response(status,out.toByteArray(),0);}public void cancel(){}}
