 static MaterialApi.Transport transport(Map<String,Object> fixture,AudioConnection connection,boolean write){return Boolean.TRUE.equals(fixture.get("production_tls"))?(write?new AudioHttp(connection):new AudioReadHttp(connection)):new Http((String)fixture.get("endpoint"),connection.token());}
 static Map<String,Object> index(LifelogAudioExport.Draft draft)throws IOException{try(ZipFile zip=new ZipFile(draft.file)){yes(zip.size()==3);return row(WireJson.read(zip.getInputStream(zip.getEntry("片段索引.json")).readAllBytes()));}}
 static byte[] rewrite(byte[] original,java.util.function.Consumer<Map<String,Object>> change)throws IOException{ByteBuffer in=ByteBuffer.wrap(original);in.position(8);int length=in.getInt();long raw=in.getLong();byte[] h=new byte[length];in.get(h);Map<String,Object> header=row(WireJson.read(h));change.accept(header);byte[] replacement=WireJson.bytes(header);ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(bytes)){out.write(Arrays.copyOf(original,8));out.writeInt(replacement.length);out.writeLong(raw);out.write(replacement);out.write(original,20+length,(int)raw);}return bytes.toByteArray();}
 static int drafts(File cache){File[] list=new File(cache,"lifelog-audio-exports").listFiles();return list==null?0:list.length;}
